/**
 * One Euro filter — low latency, low jitter smoothing for real-time tracking.
 * https://gery.casiez.net/1euro/
 */
export class OneEuroFilter {
  constructor({ minCutoff = 1.6, beta = 0.45, dCutoff = 1.0 } = {}) {
    this.minCutoff = minCutoff;
    this.beta = beta;
    this.dCutoff = dCutoff;
    this.x = null;
    this.dx = 0;
    this.lastTime = null;
  }

  reset() {
    this.x = null;
    this.dx = 0;
    this.lastTime = null;
  }

  alpha(cutoff, dt) {
    const tau = 1 / (2 * Math.PI * cutoff);
    return 1 / (1 + tau / dt);
  }

  filter(value, time) {
    if (this.x === null || this.lastTime === null) {
      this.x = value;
      this.dx = 0;
      this.lastTime = time;
      return value;
    }

    const dt = Math.max(1e-4, Math.min(0.25, time - this.lastTime));
    this.lastTime = time;

    const rawDx = (value - this.x) / dt;
    const dxAlpha = this.alpha(this.dCutoff, dt);
    this.dx += dxAlpha * (rawDx - this.dx);

    const cutoff = this.minCutoff + this.beta * Math.abs(this.dx);
    const alpha = this.alpha(cutoff, dt);
    this.x += alpha * (value - this.x);
    return this.x;
  }
}

export class Vec3Filter {
  constructor(options) {
    this.x = new OneEuroFilter(options);
    this.y = new OneEuroFilter(options);
    this.z = new OneEuroFilter(options);
    this.out = { x: 0, y: 0, z: 0 };
  }

  reset() {
    this.x.reset();
    this.y.reset();
    this.z.reset();
  }

  filter(v, time) {
    this.out.x = this.x.filter(v.x, time);
    this.out.y = this.y.filter(v.y, time);
    this.out.z = this.z.filter(v.z, time);
    return this.out;
  }
}

export class LandmarkFilter {
  constructor(count, options) {
    this.filters = Array.from({ length: count }, () => new Vec3Filter(options));
    this.out = Array.from({ length: count }, () => ({ x: 0, y: 0, z: 0 }));
  }

  reset() {
    for (const f of this.filters) f.reset();
  }

  filter(points, time) {
    for (let i = 0; i < this.filters.length; i++) {
      const p = points[i];
      if (!p) {
        this.out[i].x = 0;
        this.out[i].y = 0;
        this.out[i].z = 0;
        this.filters[i].reset();
        continue;
      }
      const v = this.filters[i].filter(p, time);
      this.out[i].x = v.x;
      this.out[i].y = v.y;
      this.out[i].z = v.z;
    }
    return this.out;
  }
}

export function lerp(a, b, t) {
  return a + (b - a) * t;
}

export function clamp(v, min = 0, max = 1) {
  return Math.min(max, Math.max(min, v));
}

export function smoothstep(edge0, edge1, x) {
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

export function damp(current, target, lambda, dt) {
  return lerp(current, target, 1 - Math.exp(-lambda * dt));
}

export function vecDistance(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  const dz = a.z - b.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

export function midpoint(a, b) {
  return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2, z: (a.z + b.z) / 2 };
}

import { clamp } from './filters.js';

const TAU = Math.PI * 2;

const add = (a, b) => ({ x: a.x + b.x, y: a.y + b.y, z: a.z + b.z });
const sub = (a, b) => ({ x: a.x - b.x, y: a.y - b.y, z: a.z - b.z });
const scale = (a, s) => ({ x: a.x * s, y: a.y * s, z: a.z * s });
const dot = (a, b) => a.x * b.x + a.y * b.y + a.z * b.z;
const length = (a) => Math.hypot(a.x, a.y, a.z);
const normalize = (a) => {
  const l = length(a) || 1;
  return { x: a.x / l, y: a.y / l, z: a.z / l };
};
const cross = (a, b) => ({
  x: a.y * b.z - a.z * b.y,
  y: a.z * b.x - a.x * b.z,
  z: a.x * b.y - a.y * b.x,
});

function rotateX(v, angle) {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return { x: v.x, y: v.y * c - v.z * s, z: v.y * s + v.z * c };
}

function rotateY(v, angle) {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return { x: v.x * c + v.z * s, y: v.y, z: -v.x * s + v.z * c };
}

function rotateZ(v, angle) {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return { x: v.x * c - v.y * s, y: v.x * s + v.y * c, z: v.z };
}

function rotateEuler(v, pitch, yaw, roll) {
  return rotateY(rotateX(rotateZ(v, roll), pitch), yaw);
}

/** Analytic two-bone IK, knee pushed toward the camera. */
function solveKnee(hip, ankle, upper = 0.42, lower = 0.42) {
  const delta = sub(ankle, hip);
  const dist = clamp(length(delta), 0.08, upper + lower - 0.002);
  const dir = normalize(delta);
  const along = (upper * upper - lower * lower + dist * dist) / (2 * dist);
  const height = Math.sqrt(Math.max(0, upper * upper - along * along));
  let perp = sub({ x: 0, y: 0, z: 1 }, scale(dir, dot({ x: 0, y: 0, z: 1 }, dir)));
  if (length(perp) < 1e-4) perp = { x: 0, y: 0, z: 1 };
  perp = normalize(perp);
  return add(add(hip, scale(dir, along)), scale(perp, height));
}

/** Build a 21-point hand skeleton. Local +Y is finger direction, +Z is palm normal. */
function handLocal(curl, spread) {
  const points = Array.from({ length: 21 }, () => ({ x: 0, y: 0, z: 0 }));
  const fingers = [
    { ids: [5, 6, 7, 8], base: { x: -0.032, y: 0.083, z: 0 }, lengths: [0.042, 0.03, 0.024], curl: 1.0 },
    { ids: [9, 10, 11, 12], base: { x: -0.009, y: 0.092, z: 0 }, lengths: [0.047, 0.034, 0.026], curl: 1.0 },
    { ids: [13, 14, 15, 16], base: { x: 0.014, y: 0.088, z: 0 }, lengths: [0.043, 0.032, 0.024], curl: 0.94 },
    { ids: [17, 18, 19, 20], base: { x: 0.037, y: 0.078, z: 0 }, lengths: [0.035, 0.026, 0.02], curl: 0.85 },
  ];

  for (const finger of fingers) {
    let p = { x: finger.base.x * spread, y: finger.base.y, z: finger.base.z };
    points[finger.ids[0]] = { ...p };
    let direction = { x: 0, y: 1, z: 0 };
    for (let i = 0; i < finger.lengths.length; i++) {
      const bend = (0.12 + i * 0.55) * curl * finger.curl;
      direction = rotateX({ x: 0, y: 1, z: 0 }, bend);
      p = add(p, scale(direction, finger.lengths[i]));
      points[finger.ids[i + 1]] = { ...p };
    }
  }

  // Thumb: CMC, MCP, IP, tip.
  const thumbBase = { x: -0.046, y: 0.018, z: 0.008 };
  points[1] = { ...thumbBase };
  points[2] = add(thumbBase, { x: -0.018, y: 0.02, z: 0.012 });
  points[3] = add(points[2], rotateX({ x: -0.012, y: 0.022, z: 0.012 }, curl * 0.35));
  points[4] = add(points[3], rotateX({ x: -0.006, y: 0.018, z: 0.01 }, curl * 0.55));

  // Palm centre point isn't a MediaPipe landmark, but wrist is.
  points[0] = { x: 0, y: 0, z: 0 };
  return points;
}

function placeHand(wrist, elbow, curl, spread) {
  const local = handLocal(curl, spread);
  let yAxis = normalize(sub(wrist, elbow));
  if (length(yAxis) < 1e-4) yAxis = { x: 0, y: -1, z: 0 };
  let xAxis = normalize(cross(yAxis, { x: 0, y: 0, z: 1 }));
  if (length(xAxis) < 1e-4) xAxis = { x: 1, y: 0, z: 0 };
  const zAxis = normalize(cross(xAxis, yAxis));
  return local.map((p) =>
    add(wrist, add(add(scale(xAxis, p.x), scale(yAxis, p.y)), scale(zAxis, p.z))),
  );
}

function blinkAt(t) {
  const cycle = 3.8;
  const phase = (t % cycle) / cycle;
  if (phase < 0.9) return 0;
  const p = (phase - 0.9) / 0.1;
  return Math.sin(p * Math.PI) ** 2;
}

export class DemoMotion {
  constructor() {
    this.started = performance.now() / 1000;
  }

  sample(t) {
    const time = t - this.started + 1.35;
    const sway = Math.sin(time * 1.15);
    const bounce = Math.max(0, Math.sin(time * 2.3)) * 0.035;
    const hipYaw = sway * 0.16;
    const hipCenter = {
      x: sway * 0.035,
      y: bounce - 0.01,
      z: Math.sin(time * 0.7) * 0.01,
    };

    const shoulderYaw = hipYaw * 0.75 + Math.sin(time * 0.55) * 0.07;
    const shoulderCenter = add(hipCenter, rotateY({ x: sway * 0.012, y: 0.515, z: 0 }, shoulderYaw));
    const shoulderHalf = rotateY({ x: 0.185, y: 0, z: 0 }, shoulderYaw);
    const shoulderL = sub(shoulderCenter, shoulderHalf);
    const shoulderR = add(shoulderCenter, shoulderHalf);

    const hipHalf = rotateY({ x: 0.098, y: 0, z: 0 }, hipYaw);
    const hipL = sub(hipCenter, hipHalf);
    const hipR = add(hipCenter, hipHalf);

    // Head / neck.
    const headYaw = Math.sin(time * 0.82 + 0.4) * 0.3;
    const headPitch = Math.sin(time * 1.3) * 0.07;
    const headRoll = Math.sin(time * 0.62) * 0.1;
    const headCenter = add(shoulderCenter, {
      x: Math.sin(time * 0.82) * 0.012,
      y: 0.255 + Math.sin(time * 2.3) * 0.006,
      z: 0.008,
    });
    const headPoint = (local) => add(headCenter, rotateEuler(local, headPitch, headYaw, headRoll));

    // Arms: side -1 = person's left, +1 = right.
    const armPose = (side, phase) => {
      const raise = 0.38 + 0.9 * (0.5 + 0.5 * Math.sin(time * 1.55 + phase));
      const theta = side * (0.3 + raise);
      const bend = 0.4 + 0.55 * (0.5 + 0.5 * Math.sin(time * 2.1 + phase * 1.7));
      const upperZ = Math.sin(time * 1.4 + phase) * 0.13;
      const foreZ = Math.sin(time * 1.9 + phase) * 0.2;
      const upperDir = normalize({ x: Math.sin(theta), y: -Math.cos(theta), z: upperZ });
      const foreDir = normalize({
        x: Math.sin(theta + side * bend),
        y: -Math.cos(theta + side * bend),
        z: foreZ,
      });
      const shoulder = side < 0 ? shoulderL : shoulderR;
      const elbow = add(shoulder, scale(upperDir, 0.275));
      const wrist = add(elbow, scale(foreDir, 0.255));
      const curl = 0.18 + 0.32 * (0.5 + 0.5 * Math.sin(time * 2.7 + phase));
      const spread = 0.95 + 0.12 * Math.sin(time * 1.8 + phase);
      return { elbow, wrist, hand: placeHand(wrist, elbow, curl, spread) };
    };

    const leftArm = armPose(-1, 0);
    const rightArm = armPose(1, 2.2);

    // Legs.
    const liftL = Math.max(0, Math.sin(time * 2.3)) * 0.055;
    const liftR = Math.max(0, Math.sin(time * 2.3 + Math.PI)) * 0.055;
    const ankleL = { x: hipL.x - 0.012, y: -0.84 + liftL, z: 0.02 + liftL * 0.8 };
    const ankleR = { x: hipR.x + 0.012, y: -0.84 + liftR, z: 0.02 + liftR * 0.8 };
    const kneeL = solveKnee(hipL, ankleL);
    const kneeR = solveKnee(hipR, ankleR);
    const heelL = add(ankleL, { x: -0.005, y: -0.018, z: -0.05 });
    const heelR = add(ankleR, { x: 0.005, y: -0.018, z: -0.05 });
    const toeL = add(ankleL, { x: -0.005, y: -0.045, z: 0.145 });
    const toeR = add(ankleR, { x: 0.005, y: -0.045, z: 0.145 });

    const world = Array.from({ length: 33 }, () => ({ x: 0, y: 0, z: 0 }));
    const set = (i, p) => {
      world[i] = p;
    };

    set(0, headPoint({ x: 0, y: -0.012, z: 0.112 }));
    set(1, headPoint({ x: -0.026, y: 0.035, z: 0.092 }));
    set(2, headPoint({ x: -0.046, y: 0.038, z: 0.088 }));
    set(3, headPoint({ x: -0.065, y: 0.032, z: 0.078 }));
    set(4, headPoint({ x: 0.026, y: 0.035, z: 0.092 }));
    set(5, headPoint({ x: 0.046, y: 0.038, z: 0.088 }));
    set(6, headPoint({ x: 0.065, y: 0.032, z: 0.078 }));
    set(7, headPoint({ x: -0.078, y: 0.012, z: -0.005 }));
    set(8, headPoint({ x: 0.078, y: 0.012, z: -0.005 }));
    set(9, headPoint({ x: -0.026, y: -0.058, z: 0.098 }));
    set(10, headPoint({ x: 0.026, y: -0.058, z: 0.098 }));
    set(11, shoulderL);
    set(12, shoulderR);
    set(13, leftArm.elbow);
    set(14, rightArm.elbow);
    set(15, leftArm.wrist);
    set(16, rightArm.wrist);
    set(17, leftArm.hand[17]);
    set(18, rightArm.hand[17]);
    set(19, leftArm.hand[5]);
    set(20, rightArm.hand[5]);
    set(21, leftArm.hand[1]);
    set(22, rightArm.hand[1]);
    set(23, hipL);
    set(24, hipR);
    set(25, kneeL);
    set(26, kneeR);
    set(27, ankleL);
    set(28, ankleR);
    set(29, heelL);
    set(30, heelR);
    set(31, toeL);
    set(32, toeR);

    // Normalized landmarks for the preview overlay.
    const landmarks = world.map((p) => ({
      x: 0.5 + p.x * 0.37,
      y: 0.5 - p.y * 0.3,
      z: p.z * 0.37,
      visibility: 1,
    }));

    const blink = blinkAt(time);
    const jawOpen = 0.12 + 0.3 * (0.5 + 0.5 * Math.sin(time * 3.1 + 0.7));
    const smile = 0.48 + 0.3 * (0.5 + 0.5 * Math.sin(time * 1.25));
    const brow = 0.3 + 0.25 * (0.5 + 0.5 * Math.sin(time * 1.7 + 1.2));
    const gazeX = Math.sin(time * 0.78) * 0.72;
    const gazeY = Math.sin(time * 1.04 + 0.6) * 0.42;
    const energy = clamp(
      0.28 + 0.32 * Math.abs(Math.sin(time * 2.3)) + 0.22 * Math.abs(Math.sin(time * 1.55)),
      0,
      1,
    );

    const eyeOpen = 1 - blink;
    return {
      mode: 'demo',
      time,
      pose: {
        world,
        landmarks,
        confidence: 0.985,
        feetConfidence: 0.965,
        bodyConfidence: 0.985,
      },
      face: {
        detected: true,
        demo: true,
        confidence: 0.972,
        blink,
        eyeOpen,
        jawOpen,
        smile,
        brow,
        gazeX,
        gazeY,
      },
      hands: [
        { handedness: 'Left', world: leftArm.hand, confidence: 0.968, demo: true },
        { handedness: 'Right', world: rightArm.hand, confidence: 0.954, demo: true },
      ],
      metrics: {
        body: 0.985,
        face: 0.972,
        hands: 1,
        feet: 0.965,
        eyes: eyeOpen,
        mouth: jawOpen,
        blink,
        jaw: jawOpen,
        smile,
        gazeX,
        gazeY,
        energy,
        points: 553,
        facePoints: 478,
      },
    };
  }
}

import {
  FilesetResolver,
  PoseLandmarker,
  FaceLandmarker,
  HandLandmarker,
} from '@mediapipe/tasks-vision';
import { clamp } from './filters.js';

const BASE = import.meta.env.BASE_URL || '/';
const MODEL_BASE = `${BASE}models/`;
const WASM_BASE = `${BASE}wasm`;

const toWorld = (lm) => ({ x: lm.x, y: -lm.y, z: -lm.z });

const averageVisibility = (landmarks, indices) => {
  if (!landmarks) return 0;
  let total = 0;
  let count = 0;
  for (const index of indices) {
    const lm = landmarks[index];
    if (!lm) continue;
    total += lm.visibility ?? 0;
    count++;
  }
  return count ? total / count : 0;
};

const blendMap = (classifications) => {
  const map = {};
  if (!classifications) return map;
  for (const category of classifications.categories ?? []) {
    map[category.categoryName] = category.score;
  }
  return map;
};

const getGaze = (face) => {
  if (!face || face.length < 478) return { x: 0, y: 0 };
  const irisLeft = averagePoint(face, [468, 469, 470, 471, 472]);
  const irisRight = averagePoint(face, [473, 474, 475, 476, 477]);
  const leftInner = face[133];
  const leftOuter = face[33];
  const rightInner = face[362];
  const rightOuter = face[263];
  const leftTop = face[159];
  const leftBottom = face[145];
  const rightTop = face[386];
  const rightBottom = face[374];

  const horizontal = (iris, a, b) => {
    const min = Math.min(a.x, b.x);
    const max = Math.max(a.x, b.x);
    const span = Math.max(1e-5, max - min);
    return ((iris.x - min) / span) * 2 - 1;
  };
  const vertical = (iris, top, bottom) => {
    const min = Math.min(top.y, bottom.y);
    const max = Math.max(top.y, bottom.y);
    const span = Math.max(1e-5, max - min);
    return ((iris.y - min) / span) * 2 - 1;
  };

  const x = (horizontal(irisLeft, leftInner, leftOuter) + horizontal(irisRight, rightInner, rightOuter)) / 2;
  const y = (vertical(irisLeft, leftTop, leftBottom) + vertical(irisRight, rightTop, rightBottom)) / 2;
  return { x: clamp(x, -1, 1), y: clamp(y, -1, 1) };
};

function averagePoint(points, indices) {
  let x = 0;
  let y = 0;
  let z = 0;
  for (const i of indices) {
    x += points[i].x;
    y += points[i].y;
    z += points[i].z;
  }
  const n = indices.length;
  return { x: x / n, y: y / n, z: z / n };
}

async function createWithFallback(Cls, vision, options) {
  try {
    return await Cls.createFromOptions(vision, {
      ...options,
      baseOptions: { ...options.baseOptions, delegate: 'GPU' },
    });
  } catch (error) {
    console.warn(`[kinetic] GPU delegate unavailable for ${Cls.name}, falling back to CPU.`, error);
    return Cls.createFromOptions(vision, {
      ...options,
      baseOptions: { ...options.baseOptions, delegate: 'CPU' },
    });
  }
}

export class MotionTracker {
  constructor() {
    this.video = document.createElement('video');
    this.video.playsInline = true;
    this.video.muted = true;
    this.video.autoplay = true;
    this.video.setAttribute('aria-hidden', 'true');
    Object.assign(this.video.style, {
      position: 'fixed',
      width: '1px',
      height: '1px',
      opacity: '0',
      pointerEvents: 'none',
      left: '-10px',
      bottom: '-10px',
    });
    document.body.appendChild(this.video);

    this.pose = null;
    this.face = null;
    this.hand = null;
    this.ready = false;
    this.stream = null;
    this.latest = null;
    this.latency = 0;
    this.lastVideoTime = -1;
    this.lastPoseAt = 0;
    this.lastFrameAt = 0;
    this.lastDetectAt = 0;
    this.detectInterval = 1000 / 30;
    this.error = null;
    this.delegate = 'GPU';
  }

  async startCamera() {
    if (!navigator.mediaDevices?.getUserMedia) {
      throw new Error('This browser does not expose a camera API.');
    }

    this.stream = await navigator.mediaDevices.getUserMedia({
      audio: false,
      video: {
        facingMode: 'user',
        width: { ideal: 1280 },
        height: { ideal: 720 },
        frameRate: { ideal: 30, max: 60 },
      },
    });

    this.video.srcObject = this.stream;
    await this.video.play();

    if (this.video.readyState < 2) {
      await new Promise((resolve) => {
        const done = () => {
          this.video.removeEventListener('loadeddata', done);
          resolve();
        };
        this.video.addEventListener('loadeddata', done);
        setTimeout(done, 2500);
      });
    }

    return {
      width: this.video.videoWidth,
      height: this.video.videoHeight,
    };
  }

  stopCamera() {
    if (this.stream) {
      for (const track of this.stream.getTracks()) track.stop();
      this.stream = null;
    }
    this.video.srcObject = null;
    this.latest = null;
  }

  async initModels(onProgress = () => {}) {
    onProgress({ progress: 0.04, label: 'Loading vision runtime' });
    const vision = await FilesetResolver.forVisionTasks(WASM_BASE);

    onProgress({ progress: 0.16, label: 'Loading body model' });
    this.pose = await createWithFallback(PoseLandmarker, vision, {
      baseOptions: {
        modelAssetPath: `${MODEL_BASE}pose_landmarker_lite.task`,
      },
      runningMode: 'VIDEO',
      numPoses: 1,
      minPoseDetectionConfidence: 0.45,
      minPosePresenceConfidence: 0.45,
      minTrackingConfidence: 0.45,
      outputSegmentationMasks: false,
    });

    onProgress({ progress: 0.5, label: 'Loading face + expression model' });
    this.face = await createWithFallback(FaceLandmarker, vision, {
      baseOptions: {
        modelAssetPath: `${MODEL_BASE}face_landmarker.task`,
      },
      runningMode: 'VIDEO',
      numFaces: 1,
      minFaceDetectionConfidence: 0.45,
      minFacePresenceConfidence: 0.45,
      minTrackingConfidence: 0.45,
      outputFaceBlendshapes: true,
      outputFacialTransformationMatrixes: true,
    });

    onProgress({ progress: 0.82, label: 'Loading hand model' });
    this.hand = await createWithFallback(HandLandmarker, vision, {
      baseOptions: {
        modelAssetPath: `${MODEL_BASE}hand_landmarker.task`,
      },
      runningMode: 'VIDEO',
      numHands: 2,
      minHandDetectionConfidence: 0.45,
      minHandPresenceConfidence: 0.45,
      minTrackingConfidence: 0.45,
    });

    this.ready = true;
    onProgress({ progress: 1, label: 'Calibrating tracking rig' });
  }

  /**
   * Run inference at ~30 Hz. Returns the newest frame, or the previous one.
   */
  detect(now) {
    if (!this.ready || !this.stream || this.video.readyState < 2) {
      return this.latest;
    }

    if (this.video.currentTime === this.lastVideoTime) {
      return this.latest;
    }

    if (now - this.lastDetectAt < this.detectInterval) {
      return this.latest;
    }

    this.lastDetectAt = now;
    this.lastVideoTime = this.video.currentTime;

    const started = performance.now();
    let poseResult = null;
    let faceResult = null;
    let handResult = null;

    try {
      poseResult = this.pose.detectForVideo(this.video, now);
    } catch (error) {
      console.warn('[kinetic] pose inference failed', error);
    }
    try {
      faceResult = this.face.detectForVideo(this.video, now);
    } catch (error) {
      console.warn('[kinetic] face inference failed', error);
    }
    try {
      handResult = this.hand.detectForVideo(this.video, now);
    } catch (error) {
      console.warn('[kinetic] hand inference failed', error);
    }

    this.latency = performance.now() - started;
    this.lastFrameAt = now;

    const poseLandmarks = poseResult?.landmarks?.[0] ?? null;
    const poseWorld = poseResult?.worldLandmarks?.[0] ?? null;
    const faceLandmarks = faceResult?.faceLandmarks?.[0] ?? null;
    const blendshapes = blendMap(faceResult?.faceBlendshapes?.[0]);
    const gaze = getGaze(faceLandmarks);

    const hands = [];
    if (handResult?.landmarks?.length) {
      for (let i = 0; i < handResult.landmarks.length; i++) {
        const handedness = handResult.handednesses?.[i]?.[0]?.categoryName ?? (i === 0 ? 'Left' : 'Right');
        const worldPoints = handResult.worldLandmarks?.[i];
        if (!worldPoints?.length) continue;

        const mapped = worldPoints.map(toWorld);
        const wrist = mapped[0];
        let anchor = null;
        if (poseWorld) {
          const poseWrist = poseWorld[handedness === 'Left' ? 15 : 16];
          if (poseWrist) anchor = toWorld(poseWrist);
        }
        if (!anchor) {
          anchor = {
            x: handedness === 'Left' ? 0.26 : -0.26,
            y: 0.16,
            z: 0.2,
          };
        }
        const offset = {
          x: anchor.x - wrist.x,
          y: anchor.y - wrist.y,
          z: anchor.z - wrist.z,
        };
        const placed = mapped.map((p) => ({
          x: p.x + offset.x,
          y: p.y + offset.y,
          z: p.z + offset.z,
        }));

        hands.push({
          handedness,
          world: placed,
          landmarks: handResult.landmarks[i],
          confidence: 0.95,
          demo: false,
        });
      }
    }

    const bodyConfidence = poseLandmarks
      ? averageVisibility(poseLandmarks, [11, 12, 13, 14, 15, 16, 23, 24, 25, 26, 27, 28])
      : 0;
    const feetConfidence = poseLandmarks
      ? averageVisibility(poseLandmarks, [27, 28, 29, 30, 31, 32])
      : 0;
    const blink = clamp(((blendshapes.eyeBlinkLeft ?? 0) + (blendshapes.eyeBlinkRight ?? 0)) / 2);
    const jaw = clamp(blendshapes.jawOpen ?? 0);
    const smile = clamp(
      ((blendshapes.mouthSmileLeft ?? 0) + (blendshapes.mouthSmileRight ?? 0)) / 2,
    );
    const eyeOpen = 1 - blink;

    if (poseLandmarks) this.lastPoseAt = now;

    const metrics = {
      body: bodyConfidence,
      face: faceLandmarks ? 1 : 0,
      hands: hands.length / 2,
      feet: feetConfidence,
      eyes: faceLandmarks ? eyeOpen : 0,
      mouth: faceLandmarks ? jaw : 0,
      blink,
      jaw,
      smile,
      gazeX: gaze.x,
      gazeY: gaze.y,
      energy: 0,
      points: (poseLandmarks ? 33 : 0) + (faceLandmarks?.length ?? 0) + hands.length * 21,
      facePoints: faceLandmarks?.length ?? 0,
    };

    this.latest = {
      mode: 'camera',
      time: now / 1000,
      pose: poseLandmarks
        ? {
            world: poseWorld ? poseWorld.map(toWorld) : null,
            landmarks: poseLandmarks,
            confidence: bodyConfidence,
            bodyConfidence,
            feetConfidence,
          }
        : null,
      face: faceLandmarks
        ? {
            landmarks: faceLandmarks,
            blendshapes,
            demo: false,
            detected: true,
            confidence: 1,
            blink,
            eyeOpen,
            jawOpen: jaw,
            smile,
            brow: blendshapes.browInnerUp ?? 0,
            gazeX: gaze.x,
            gazeY: gaze.y,
          }
        : null,
      hands,
      metrics,
      latency: this.latency,
      delegate: this.delegate,
    };

    return this.latest;
  }

  dispose() {
    this.stopCamera();
    this.pose?.close?.();
    this.face?.close?.();
    this.hand?.close?.();
    this.pose = null;
    this.face = null;
    this.hand = null;
    this.ready = false;
  }
}

import * as THREE from 'three';

let glowTexture = null;

export function getGlowTexture() {
  if (glowTexture) return glowTexture;
  const size = 128;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  const gradient = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  gradient.addColorStop(0, 'rgba(255,255,255,1)');
  gradient.addColorStop(0.16, 'rgba(255,255,255,0.95)');
  gradient.addColorStop(0.38, 'rgba(255,255,255,0.32)');
  gradient.addColorStop(0.7, 'rgba(255,255,255,0.05)');
  gradient.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, size, size);
  glowTexture = new THREE.CanvasTexture(canvas);
  glowTexture.colorSpace = THREE.SRGBColorSpace;
  glowTexture.needsUpdate = true;
  return glowTexture;
}

export function glowPointMaterial(color, size = 0.03, opacity = 0.9) {
  return new THREE.PointsMaterial({
    color,
    size,
    map: getGlowTexture(),
    transparent: true,
    opacity,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    sizeAttenuation: true,
    alphaTest: 0.001,
  });
}

export function glowSprite(color, scale = 0.2, opacity = 0.5) {
  const material = new THREE.SpriteMaterial({
    map: getGlowTexture(),
    color,
    transparent: true,
    opacity,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  });
  const sprite = new THREE.Sprite(material);
  sprite.scale.setScalar(scale);
  return sprite;
}

export function neonLineMaterial(color, opacity = 0.8) {
  return new THREE.LineBasicMaterial({
    color,
    transparent: true,
    opacity,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  });
}

export function setGeometryPositions(geometry, positions, count) {
  const attr = geometry.getAttribute('position');
  if (!attr) return;
  attr.array.set(positions);
  attr.needsUpdate = true;
  geometry.setDrawRange(0, count);
  geometry.computeBoundingSphere();
}

export function createPositionsBuffer(count) {
  return new Float32Array(count * 3);
}

import * as THREE from 'three';
import { glowPointMaterial, neonLineMaterial } from './glow.js';

export const HAND_CONNECTIONS = [
  [0, 1],
  [1, 2],
  [2, 3],
  [3, 4],
  [0, 5],
  [5, 6],
  [6, 7],
  [7, 8],
  [5, 9],
  [9, 10],
  [10, 11],
  [11, 12],
  [9, 13],
  [13, 14],
  [14, 15],
  [15, 16],
  [13, 17],
  [17, 18],
  [18, 19],
  [19, 20],
  [0, 17],
];

const TIPS = [4, 8, 12, 16, 20];

export class HandRig {
  constructor(color = 0xff5ecf) {
    this.group = new THREE.Group();
    this.group.visible = false;

    this.bonePositions = new Float32Array(HAND_CONNECTIONS.length * 2 * 3);
    const boneGeo = new THREE.BufferGeometry();
    boneGeo.setAttribute('position', new THREE.BufferAttribute(this.bonePositions, 3));
    this.bones = new THREE.LineSegments(boneGeo, neonLineMaterial(color, 0.92));
    this.group.add(this.bones);

    this.jointPositions = new Float32Array(21 * 3);
    const jointGeo = new THREE.BufferGeometry();
    jointGeo.setAttribute('position', new THREE.BufferAttribute(this.jointPositions, 3));
    this.joints = new THREE.Points(jointGeo, glowPointMaterial(color, 0.026, 0.95));
    this.group.add(this.joints);

    this.tipPositions = new Float32Array(TIPS.length * 3);
    const tipGeo = new THREE.BufferGeometry();
    tipGeo.setAttribute('position', new THREE.BufferAttribute(this.tipPositions, 3));
    this.tips = new THREE.Points(tipGeo, glowPointMaterial(0xffffff, 0.038, 0.9));
    this.group.add(this.tips);

    this.palmPositions = new Float32Array(3 * 3);
    const palmGeo = new THREE.BufferGeometry();
    palmGeo.setAttribute('position', new THREE.BufferAttribute(this.palmPositions, 3));
    palmGeo.setIndex([0, 1, 2]);
    this.palm = new THREE.Mesh(
      palmGeo,
      new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 0.12,
        side: THREE.DoubleSide,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    );
    this.group.add(this.palm);

    this.wristGlow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: null,
        color,
        transparent: true,
        opacity: 0.4,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    );
    this.wristGlow.visible = false;
    this.group.add(this.wristGlow);
  }

  update(points, confidence = 1) {
    if (!points || points.length < 21) {
      this.group.visible = false;
      return;
    }
    this.group.visible = true;

    for (let i = 0; i < HAND_CONNECTIONS.length; i++) {
      const [a, b] = HAND_CONNECTIONS[i];
      const pa = points[a];
      const pb = points[b];
      const offset = i * 6;
      this.bonePositions[offset] = pa.x;
      this.bonePositions[offset + 1] = pa.y;
      this.bonePositions[offset + 2] = pa.z;
      this.bonePositions[offset + 3] = pb.x;
      this.bonePositions[offset + 4] = pb.y;
      this.bonePositions[offset + 5] = pb.z;
    }
    this.bones.geometry.getAttribute('position').needsUpdate = true;

    for (let i = 0; i < 21; i++) {
      this.jointPositions[i * 3] = points[i].x;
      this.jointPositions[i * 3 + 1] = points[i].y;
      this.jointPositions[i * 3 + 2] = points[i].z;
    }
    this.joints.geometry.getAttribute('position').needsUpdate = true;

    for (let i = 0; i < TIPS.length; i++) {
      const p = points[TIPS[i]];
      this.tipPositions[i * 3] = p.x;
      this.tipPositions[i * 3 + 1] = p.y;
      this.tipPositions[i * 3 + 2] = p.z;
    }
    this.tips.geometry.getAttribute('position').needsUpdate = true;

    const palm = [points[0], points[5], points[17]];
    for (let i = 0; i < 3; i++) {
      this.palmPositions[i * 3] = palm[i].x;
      this.palmPositions[i * 3 + 1] = palm[i].y;
      this.palmPositions[i * 3 + 2] = palm[i].z;
    }
    this.palm.geometry.getAttribute('position').needsUpdate = true;

    const alpha = Math.min(1, Math.max(0.25, confidence));
    this.bones.material.opacity = 0.92 * alpha;
    this.joints.material.opacity = 0.95 * alpha;
  }

  dispose() {
    this.group.traverse((obj) => {
      obj.geometry?.dispose?.();
      if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose?.());
      else obj.material?.dispose?.();
    });
  }
}

