    map: getGlowTexture(),
    vertexColors: true,
    transparent: true,
    opacity: 0.62,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    sizeAttenuation: true,
    alphaTest: 0.001,
  });

  this.particles = new THREE.Points(geometry, material);
  this.particles.frustumCulled = false;
  this.scene.add(this.particles);
}

