184:     this.setRow('eyes', eyes, face > 0.5 ? pct(eyes) : '—');
185:     this.setRow('mouth', mouth, face > 0.5 ? pct(mouth) : '—');
186: 
187:     for (const chip of this.el.mobileChips) {
188:       const name = chip.dataset.mm;
189:       const value =
190:         name === 'body'
191:           ? pct(body)
192:           : name === 'face'
193:             ? face > 0.5
194:               ? 'ON'
