216:     const gazeX = clamp(metrics.gazeX ?? 0, -1, 1);
217:     const gazeY = clamp(metrics.gazeY ?? 0, -1, 1);
218:     const gazeTransform = `translate(${(gazeX * 22).toFixed(1)}px, ${(-gazeY * 22).toFixed(1)}px)`;
219:     if (this.cache.gaze !== gazeTransform) {
220:       this.cache.gaze = gazeTransform;
221:       this.el.gazeDot.style.transform = gazeTransform;
222:       this.el.gazeValue.textContent = `${gazeX >= 0 ? '+' : ''}${gazeX.toFixed(2)} / ${gazeY >= 0 ? '+' : ''}${gazeY.toFixed(2)}`;
223:     }
224: 
225:     const blink = clamp(metrics.blink ?? 0);
226:     const jaw = clamp(metrics.jaw ?? mouth);
227:     const smile = clamp(metrics.smile ?? 0);
228:     this.setMeter('blink', this.el.blinkMeter, blink);
