247:   setRow(name, value, label) {
248:     const row = this.rows[name];
249:     if (!row) return;
250:     const cached = this.cache.rows[name];
251:     if (!cached || Math.abs(cached.value - value) > 0.008) {
252:       row.bar.style.width = pct(value);
253:       this.cache.rows[name] = { ...(cached || {}), value };
254:     }
255:     if (!cached || cached.label !== label) {
