262:       this.cache.rows[name] = { ...(this.cache.rows[name] || {}), active };
263:     }
264:   }
265: 
266:   setText(key, element, text) {
267:     if (!element) return;
268:     if (this.cache.values[key] === text) return;
269:     this.cache.values[key] = text;
270:     element.textContent = text;
271:   }
272: 
273:   setMeter(key, element, value) {
274:     if (!element) return;
275:     const cached = this.cache.meters[key];
276:     if (cached !== undefined && Math.abs(cached - value) < 0.008) return;
277:     this.cache.meters[key] = value;
278:     element.style.width = pct(value);
279:   }
280: 
281:   pushEnergy(value) {
282:     this.history.push(value);
283:     if (this.history.length > 64) this.history.shift();
284:     this.drawEnergy();
285:   }
286: 
287:   drawEnergy() {
288:     const ctx = this.energyCtx;
289:     const w = this.energyCanvasW;
290:     const h = this.energyCanvasH;
291:     ctx.clearRect(0, 0, w, h);
292: 
293:     ctx.strokeStyle = 'rgba(95,245,255,0.07)';
294:     ctx.lineWidth = 1;
295:     for (let y = 8; y < h; y += 10) {
296:       ctx.beginPath();
297:       ctx.moveTo(0, y + 0.5);
298:       ctx.lineTo(w, y + 0.5);
299:       ctx.stroke();
300:     }
301: 
302:     if (this.history.length < 2) return;
303:     const step = w / (this.history.length - 1);
304:     const points = this.history.map((v, i) => [i * step, h - 3 - v * (h - 8)]);
305: 
306:     const gradient = ctx.createLinearGradient(0, 0, 0, h);
307:     gradient.addColorStop(0, 'rgba(95,245,255,0.22)');
308:     gradient.addColorStop(1, 'rgba(95,245,255,0)');
309:     ctx.beginPath();
310:     ctx.moveTo(points[0][0], h);
311:     for (const [x, y] of points) ctx.lineTo(x, y);
312:     ctx.lineTo(points[points.length - 1][0], h);
313:     ctx.closePath();
314:     ctx.fillStyle = gradient;
315:     ctx.fill();
316: 
317:     ctx.beginPath();
318:     points.forEach(([x, y], i) => {
319:       if (i === 0) ctx.moveTo(x, y);
320:       else ctx.lineTo(x, y);
321:     });
322:     ctx.strokeStyle = 'rgba(95,245,255,0.85)';
323:     ctx.lineWidth = 1.2;
324:     ctx.shadowColor = 'rgba(95,245,255,0.8)';
325:     ctx.shadowBlur = 6;
326:     ctx.stroke();
327:     ctx.shadowBlur = 0;
328: 
329:     const last = points[points.length - 1];
330:     ctx.beginPath();
331:     ctx.arc(last[0], last[1], 1.6, 0, Math.PI * 2);
332:     ctx.fillStyle = '#f2feff';
333:     ctx.fill();
334:   }
335: }

