function makeEnvironment(renderer) {
  const canvas = document.createElement('canvas');
  canvas.width = 512; canvas.height = 256;
  const ctx = canvas.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 0, 256);
  g.addColorStop(0, '#0a3340');
  g.addColorStop(0.42, '#061821');
  g.addColorStop(0.55, '#030a10');
  g.addColorStop(1, '#010306');
  ctx.fillStyle = g; ctx.fillRect(0,0,512,256);
  // cyan key blob upper-left-ish, magenta rim right
  const blob = (x,y,r,c) => { const rg = ctx.createRadialGradient(x,y,0,x,y,r); rg.addColorStop(0,c); rg.addColorStop(1,'rgba(0,0,0,0)'); ctx.fillStyle=rg; ctx.fillRect(x-r,y-r,r*2,r*2); };
